export async function logPageView(page: string) {
  // Simulate analytics API call
  console.log(`[Analytics] Logging page view for: ${page}`);

  // Simulate network delay
  await new Promise(resolve => setTimeout(resolve, 100));

  // In a real implementation, you would send data to your analytics service
  // e.g., await fetch('https://analytics.example.com/track', { ... })

  console.log(`[Analytics] Successfully logged page view for: ${page}`);
}

