import { after } from 'next/server';
import { logPageView } from './analytics';

export default function Home() {
  // Schedule analytics logging to run after the response is sent
  // This does NOT block the response to the client
  after(() => {
    logPageView('/');
  });

  return (
    <main>
      <h1>Welcome to Our Site!</h1>
      <p>This page logs analytics without blocking the response.</p>
      <p>The page view has been tracked asynchronously.</p>
    </main>
  );
}

